import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_indexOf_TriageGen0Test {







    @Test
    public void testIndexOf_StartIndexOutOfBounds() {
        StrBuilder sb = new StrBuilder("hello");
        // startIndex >= size returns -1
        assertEquals(-1, sb.indexOf("h", 5));
        assertEquals(-1, sb.indexOf("h", 10));
        // startIndex < 0 is treated as 0
        assertEquals(0, sb.indexOf("h", -5));
    }














}

